-- Retail Banking dataset (generated by scripts/build_datasets.py; do not edit by hand)
DROP TABLE IF EXISTS loans CASCADE;
DROP TABLE IF EXISTS transactions CASCADE;
DROP TABLE IF EXISTS accounts CASCADE;
DROP TABLE IF EXISTS customers CASCADE;
DROP TABLE IF EXISTS branches CASCADE;

CREATE TABLE branches (
  branch_id INTEGER PRIMARY KEY,
  branch_name VARCHAR(60) NOT NULL,
  city VARCHAR(60) NOT NULL,
  opened_date DATE NOT NULL
);

CREATE TABLE customers (
  customer_id INTEGER PRIMARY KEY,
  first_name VARCHAR(40) NOT NULL,
  last_name VARCHAR(40) NOT NULL,
  date_of_birth DATE NOT NULL,
  email VARCHAR(120),
  phone VARCHAR(20),
  city VARCHAR(60),
  joined_date DATE NOT NULL,
  kyc_status VARCHAR(10) NOT NULL CHECK (kyc_status IN ('verified','pending','rejected'))
);

CREATE TABLE accounts (
  account_id INTEGER PRIMARY KEY,
  customer_id INTEGER NOT NULL REFERENCES customers(customer_id),
  branch_id INTEGER NOT NULL REFERENCES branches(branch_id),
  account_type VARCHAR(10) NOT NULL CHECK (account_type IN ('checking','savings','business')),
  opened_date DATE NOT NULL,
  closed_date DATE,
  status VARCHAR(10) NOT NULL CHECK (status IN ('open','closed','frozen')),
  balance NUMERIC(14,2) NOT NULL,
  CHECK (closed_date IS NULL OR closed_date >= opened_date),
  CHECK ((status = 'closed') = (closed_date IS NOT NULL))
);

CREATE TABLE transactions (
  transaction_id INTEGER PRIMARY KEY,
  account_id INTEGER NOT NULL REFERENCES accounts(account_id),
  txn_time TIMESTAMP NOT NULL,
  txn_type VARCHAR(12) NOT NULL CHECK (txn_type IN ('deposit','withdrawal','transfer_in','transfer_out','fee','interest')),
  direction CHAR(1) NOT NULL CHECK (direction IN ('C','D')),
  amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
  counterparty_account_id INTEGER REFERENCES accounts(account_id),
  description VARCHAR(120)
);

CREATE TABLE loans (
  loan_id INTEGER PRIMARY KEY,
  customer_id INTEGER NOT NULL REFERENCES customers(customer_id),
  branch_id INTEGER NOT NULL REFERENCES branches(branch_id),
  loan_type VARCHAR(12) NOT NULL CHECK (loan_type IN ('mortgage','auto','personal','student')),
  principal NUMERIC(12,2) NOT NULL CHECK (principal > 0),
  interest_rate NUMERIC(5,2) NOT NULL CHECK (interest_rate BETWEEN 0 AND 30),
  start_date DATE NOT NULL,
  term_months INTEGER NOT NULL CHECK (term_months > 0),
  status VARCHAR(10) NOT NULL CHECK (status IN ('active','paid_off','defaulted','pending'))
);


















